from .scfc_analyzer import ScfcAnalyzer
from robot.libraries.BuiltIn import BuiltIn
from robot.libraries.XML import XML


def get_log_path():
    """Gets path to log directory from robotlte."""
    output_directory = "${OUTPUT_DIR}"
    return BuiltIn().get_variable_value(output_directory)


def get_test_name():
    """Gets test name from robotlte."""
    test_name = "${TEST NAME}"
    return BuiltIn().get_variable_value(test_name)


def create_scf_analyzer():
    """Create an instance of ScfAnalyzer."""
    return ScfcAnalyzer(get_test_name(), get_log_path(), XML())


class ta5g_scfc_analysis(object):
    def get_latest_scfc(self, output_filename=None, host_ip='127.0.0.1', timeout=60):
        """Gets the lastest scfc file and returns it's path."""
        return create_scf_analyzer().get_latest_scfc(output_filename, host_ip, timeout)

    def managed_object_should_exist_in_latest_scfc(self, object_path, scfc_filename=None):
        """Checks if given xpath to managed object exists in given scfc filename."""
        return create_scf_analyzer().check_if_managed_object_exists(object_path, scfc_filename)

    def managed_object_should_not_exist_in_latest_scfc(self, object_path, scfc_filename=None):
        """Checks if given xpath to managed object doest not exist in given scfc filename."""
        return create_scf_analyzer().check_if_managed_object_does_not_exist(object_path, scfc_filename)
